let serviceStep=0;function setServiceStep(index){serviceStep=index;document.querySelectorAll('[data-service-step]').forEach(el=>el.hidden=Number(el.dataset.serviceStep)!==index);document.querySelectorAll('[data-step-label]').forEach(el=>el.classList.toggle('active',Number(el.dataset.stepLabel)===index));$('#previous-step').hidden=index===0;$('#next-step').hidden=index===2;$('#save-service').hidden=index!==2;$('#wizard-status').textContent='الخطوة '+(index+1)+' من 3'}
