let noticeDismissVersion=0;function dismissAdminNotice(){clearTimeout(noticeTimer);const notice=$('#admin-notice');if(notice.hidden)return;notice.hidden=true;if(!matchMedia('(prefers-reduced-motion: reduce)').matches){notice.hidden=false;const animation=notice.animate([{opacity:1,transform:'translateX(-50%) translateY(0)'},{opacity:0,transform:'translateX(-50%) translateY(10px)'}],{duration:160,easing:'ease-in'});const version=noticeDismissVersion;animation.finished.then(()=>{if(version===noticeDismissVersion)notice.hidden=true}).catch(()=>{})}}
