$('#service-image').onchange=async()=>{const file=$('#service-image').files[0];if(!file)return;const version=++imageVersion;imageBusy=true;$('#next-step').disabled=true;$('#save-service').disabled=true;$('#image-feedback').textContent='جارٍ تجهيز الصورة…';try{const data=await OwaysImages.prepare(file);if(version!==imageVersion)return;serviceImage=data;$('#service-image-preview').src=data;$('#image-preview').hidden=false;$('#image-feedback').textContent='الصورة جاهزة بمقاس 960 × 600، مع قص مركزي لملء البطاقة. راجع المعاينة قبل الحفظ.'}catch(e){if(version!==imageVersion)return;$('#service-image').value='';$('#image-feedback').textContent=e.message+(serviceImage?' الصورة السابقة ما زالت محفوظة.':'');status(e.message);$('#admin-notice').classList.add('error')}finally{if(version===imageVersion){imageBusy=false;$('#next-step').disabled=false;$('#save-service').disabled=false}}};
