const quickCategoryDialog=$('#quick-category-dialog'),quickCategoryForm=$('#quick-category-form');
$('#quick-category-open').onclick=()=>{quickCategoryForm.reset();$('#quick-category-feedback').textContent='';quickCategoryDialog.showModal();quickCategoryForm.elements.name.focus()};
$('#quick-category-close').onclick=()=>quickCategoryDialog.close();
quickCategoryForm.onsubmit=async event=>{
 event.preventDefault();const feedback=$('#quick-category-feedback');
 const data=Object.fromEntries(new FormData(quickCategoryForm));data.name=data.name.trim();
 if(!data.name){feedback.textContent='أدخل اسم التصنيف قبل الحفظ.';quickCategoryForm.elements.name.focus();return}
 feedback.textContent='جارٍ حفظ التصنيف…';
 try{
  const result=await api('/api/admin/categories',data);
  const option=document.createElement('option');option.value=result.id;option.textContent=data.name;
  $('#category-select').append(option);$('#category-select').value=String(result.id);
  $('#category-select').dispatchEvent(new Event('change',{bubbles:true}));
  quickCategoryDialog.close();status('تم إضافة التصنيف واختياره للخدمة.');
  $('#category-select').focus();
  try{await refresh();$('#category-select').value=String(result.id)}catch{status('تم حفظ التصنيف. تعذر تحديث القائمة، أعد تحديثها لاحقًا.')}
 }catch(error){feedback.textContent=error.message}
};

function cleanContactNumber(value){
 let number=value.replace(/[٠-٩۰-۹]/g,c=>String(c.charCodeAt(0)>=1776?c.charCodeAt(0)-1776:c.charCodeAt(0)-1632)).replace(/[^+0-9]/g,'');
 if(number.startsWith('00'))number='+'+number.slice(2);
 return number;
}
function renderContactPreview(){
 const form=$('#contact-form'),labels={whatsapp:'واتساب',phone:'الهاتف',email:'البريد الإلكتروني',hours:'أوقات العمل',address:'العنوان'};
 const container=$('#contact-preview-items');container.replaceChildren();
 for(const [key,label]of Object.entries(labels)){
  const value=form.elements[key].value.trim();if(!value)continue;
  const row=document.createElement('div'),title=document.createElement('small'),text=document.createElement('span');
  row.className='contact-preview-row';title.textContent=label;text.textContent=value;if(['whatsapp','phone','email'].includes(key))text.dir='ltr';row.append(title,text);container.append(row);
 }
 if(!container.children.length){const p=document.createElement('p');p.textContent='أضف وسيلة تواصل لتظهر هنا.';container.append(p)}
}
$('#contact-form').addEventListener('input',event=>{
 const field=event.target;if(['whatsapp','phone'].includes(field.name))field.value=cleanContactNumber(field.value);
 const error=document.querySelector('[data-contact-error="'+field.name+'"]');if(error)error.textContent='';
 field.removeAttribute('aria-invalid');$('#contact-save-state').textContent='لديك تعديلات لم تُحفظ بعد.';renderContactPreview();
});



let editingService=null;
function resetServiceEditor(){editingService=null;imageVersion++;imageBusy=false;serviceForm.reset();clearServiceImage();$('#requirements').replaceChildren();updateDuration();serviceForm.elements.pricing_mode.dispatchEvent(new Event('change'));setServiceStep(0);$('#save-service').textContent='حفظ الخدمة';}
function renderPopularServices(items){let panel=$('#popular-services');if(!panel){panel=document.createElement('section');panel.id='popular-services';panel.className='portal-panel popular-services';$('#services-list').prepend(panel)}const used=items.filter(x=>Number(x.order_count)>0),max=Number(used[0]?.order_count)||1;panel.innerHTML='<h3>الخدمات الأكثر طلبًا</h3><p class="fine">أعلى 10 خدمات حسب عدد الطلبات غير الملغاة، منذ بداية الموقع.</p>'+ (used.length?used.map((x,i)=>`<div class="popular-service-row"><span>${i+1}. ${E(x.name)}${x.status==='archived'?' (محذوفة)':''}</span><strong>${E(x.order_count)} طلب</strong><progress max="${max}" value="${Number(x.order_count)}" aria-label="عدد طلبات ${E(x.name)}"></progress></div>`).join(''):'<p class="fine">ستظهر الإحصائية عند وصول أول طلب.</p>')}
document.addEventListener('click',event=>{const edit=event.target.closest('[data-edit-service]'),remove=event.target.closest('[data-delete-service]');if(edit)run(async()=>{const {service:s}=await api('/api/admin/services/'+edit.dataset.editService),p=s.packages.find(p=>String(p.id)===edit.dataset.package);if(!p)throw Error('الباقة غير موجودة.');resetServiceEditor();editingService={id:s.id,slug:s.slug,package_id:p.id};for(const [key,value] of Object.entries({...s,...p,category_id:s.category_id,name:s.name,description:s.description,status:s.status,featured:s.featured?'1':'0',discount_percent:p.discount_percent||0,kind:s.kind,package_name:p.name,features:(typeof s.features==='string'?JSON.parse(s.features):s.features||[]).join('\n')})){const field=serviceForm.elements.namedItem(key);if(field&&'value' in field)field.value=value??''}updateDuration();serviceForm.elements.pricing_mode.dispatchEvent(new Event('change'));const images=typeof s.images==='string'?JSON.parse(s.images):s.images;serviceImage=images?.[0]?.src||null;if(serviceImage){$('#service-image-preview').src=serviceImage;$('#image-preview').hidden=false}for(const instruction of p.instructions)serviceForm.elements[instruction.stage].value=instruction.body;for(const r of p.requirements){$('#add-requirement').click();const row=$('#requirements').lastElementChild;for(const [selector,value]of [['[data-key]',r.field_key],['[data-label]',r.label],['[data-type]',r.input_type],['[data-help]',r.help_text||''],['[data-options]',(typeof r.options_json==='string'?JSON.parse(r.options_json):r.options_json||[]).join('\n')]])row.querySelector(selector).value=value;row.querySelector('[data-required]').checked=!!r.required;row.querySelector('[data-type]').dispatchEvent(new Event('change'))}updateDiscountPreview();$('#save-service').textContent='حفظ التعديلات';setServiceStep(0);$('#service-editor').hidden=false;$('#service-editor').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});serviceForm.elements.name.focus({preventScroll:true})});if(remove){const s=adminServices.find(s=>String(s.id)===remove.dataset.deleteService);$('#delete-service-name').textContent=s?.name||'';$('#delete-service-dialog').dataset.serviceId=remove.dataset.deleteService;$('#delete-service-dialog').showModal()}});
$('#cancel-service-delete').onclick=()=>$('#delete-service-dialog').close();$('#confirm-service-delete').onclick=()=>run(async()=>{const dialog=$('#delete-service-dialog'),button=$('#confirm-service-delete');button.disabled=true;try{await api('/api/admin/services/'+dialog.dataset.serviceId+'/delete',{});dialog.close();if(String(editingService?.id)===dialog.dataset.serviceId){resetServiceEditor();$('#service-editor').hidden=true}status('تم حذف الخدمة من العرض، مع حفظ الطلبات السابقة.');await refreshAfterSave()}finally{button.disabled=false}});

let managedCategories=[];
const actionIcon=kind=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(kind==='edit'?'<path d="m16 3 5 5-12 12-6 1 1-6L16 3Z M14 5l5 5"/>':'<path d="M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7"/>')+'</svg>';
function renderCategories(categories){managedCategories=categories;$('#categories').innerHTML=categories.length?categories.map(c=>`<article class="category-manage-card"><div><h3>${E(c.name)}</h3><p>${E(c.description||'بدون وصف')}</p></div><div class="category-manage-actions"><button type="button" class="button outline" data-edit-category="${E(c.id)}">${actionIcon('edit')}<span>تعديل</span></button><button type="button" class="button outline danger-action" data-delete-category="${E(c.id)}">${actionIcon('delete')}<span>حذف</span></button></div></article>`).join(''):'<p class="fine">لا توجد تصنيفات بعد.</p>'}
document.addEventListener('click',event=>{const edit=event.target.closest('[data-edit-category]'),remove=event.target.closest('[data-delete-category]');if(!edit&&!remove)return;const c=managedCategories.find(c=>String(c.id)===(edit?.dataset.editCategory||remove.dataset.deleteCategory));if(!c)return;if(edit){const f=$('#edit-category-form');f.dataset.categoryId=c.id;f.elements.name.value=c.name;f.elements.description.value=c.description||'';$('#edit-category-feedback').textContent='';$('#edit-category-dialog').showModal();f.elements.name.focus()}else{const d=$('#delete-category-dialog');d.dataset.categoryId=c.id;$('#delete-category-label').textContent=c.name;$('#delete-category-feedback').textContent='';d.showModal()}});
$('#close-category-edit').onclick=()=>$('#edit-category-dialog').close();$('#cancel-category-delete').onclick=()=>$('#delete-category-dialog').close();
$('#edit-category-form').onsubmit=event=>{event.preventDefault();run(async()=>{const f=event.target;try{await api('/api/admin/categories/'+f.dataset.categoryId,Object.fromEntries(new FormData(f)));$('#edit-category-dialog').close();status('تم تعديل التصنيف.');await refreshAfterSave()}catch(error){$('#edit-category-feedback').textContent=error.message}})};
$('#confirm-category-delete').onclick=()=>run(async()=>{const d=$('#delete-category-dialog'),button=$('#confirm-category-delete');button.disabled=true;try{await api('/api/admin/categories/'+d.dataset.categoryId+'/delete',{});d.close();status('تم حذف التصنيف.');await refreshAfterSave()}catch(error){$('#delete-category-feedback').textContent=error.message}finally{button.disabled=false}});

function updateDiscountPreview(){const f=serviceForm.elements,isFixed=f.pricing_mode.value==='fixed',input=f.discount_percent;input.disabled=!isFixed;input.closest('label').hidden=!isFixed;const price=Number(f.price.value),percent=Number(input.value);$('#discount-preview').textContent=isFixed&&Number.isFinite(price)&&percent>=0&&percent<=100?'السعر بعد الحسم: '+(Math.round(Math.round(price*100)*(100-percent)/100)/100).toFixed(2)+' '+f.currency.value:''}
serviceForm.addEventListener('input',updateDiscountPreview);serviceForm.addEventListener('change',updateDiscountPreview);serviceForm.addEventListener('reset',()=>queueMicrotask(updateDiscountPreview));
let homepageLoaded=false,homepageCategories=[];
function loadHomepageCategories(categories){homepageCategories=categories;if(!homepageLoaded){run(loadHomepage);return}const selected=new Set(new FormData($('#homepage-form')).getAll('featured_category_ids'));$('#homepage-categories').innerHTML=categories.map(c=>`<label><input type="checkbox" name="featured_category_ids" value="${E(c.id)}" ${selected.has(String(c.id))?'checked':''}>${E(c.name)}</label>`).join('')}
async function loadHomepage(){const config=await api('/api/admin/homepage');const form=$('#homepage-form');for(const key of ['title','subtitle','banner'])form.elements[key].value=config[key]||'';const selected=new Set((config.featured_category_ids||[]).map(String));$('#homepage-categories').innerHTML=homepageCategories.map(c=>`<label><input type="checkbox" name="featured_category_ids" value="${E(c.id)}" ${selected.has(String(c.id))?'checked':''}>${E(c.name)}</label>`).join('');homepageLoaded=true}
$('#homepage-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('[type=submit]'),feedback=$('#homepage-feedback');if(button.disabled)return;button.disabled=true;feedback.textContent='جارٍ الحفظ…';try{const data=Object.fromEntries(new FormData(form));data.featured_category_ids=new FormData(form).getAll('featured_category_ids');await api('/api/admin/homepage',data);feedback.textContent='تم حفظ إعدادات الصفحة الرئيسية.'}catch(error){feedback.textContent=error.message}finally{button.disabled=false}};
